// Rien n'empêche d'ajouter un sous-type n'importe où.
abstract class Paiement {
    abstract double montant();
}

class CarteBancaire extends Paiement {
    double montant() { return 10.0; }
}

class Virement extends Paiement {
    double montant() { return 20.0; }
}

// Demain, quelqu'un ajoute ceci SANS te prevenir, dans un autre fichier :
class BitcoinDouteux extends Paiement {
    double montant() { return 0.0; }
}
// Ton code qui traite "tous les paiements possibles" est maintenant incomplet,
// et tu ne le sais meme pas.

// Paiement est scellee : seuls CarteBancaire et Virement peuvent en heriter.
public sealed class Paiement permits CarteBancaire, Virement {
    // ... contenu commun ...
}

// Chaque sous-type autorise DOIT choisir son propre regime (voir lecon suivante).
final class CarteBancaire extends Paiement { }
final class Virement extends Paiement { }

// Ceci ne COMPILE PAS : Especes n'est pas dans la liste permits.
// final class Especes extends Paiement { } // erreur du compilateur

// Si tous les sous-types sont dans le MEME fichier source,
// la clause permits devient facultative : le compilateur la deduit.
public sealed class Paiement {
    // permits CarteBancaire, Virement est implicite ici
}

final class CarteBancaire extends Paiement { }
final class Virement extends Paiement { }

// Pratique pour une petite hierarchie : tout tient sous les yeux,
// et on n'a pas a maintenir la liste permits a la main.

