public sealed class Vehicule permits Voiture, Camion, Jouet { }

// final : rien ne peut heriter de Voiture.
final class Voiture extends Vehicule { }

// sealed : Camion controle a son tour qui l'etend.
sealed class Camion extends Vehicule permits Benne { }
final class Benne extends Camion { }

// non-sealed : Jouet rouvre la porte, n'importe qui peut etendre Jouet.
non-sealed class Jouet extends Vehicule { }
class PetiteVoitureEnPlastique extends Jouet { } // autorise, car Jouet est non-sealed

// L'interface Forme autorise exactement trois formes, pas une de plus.
public sealed interface Forme permits Cercle, Rectangle, Triangle { }

// Les records sont implicitement final : sous-types parfaits d'une interface scellee.
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

// Impossible d'ajouter une 4e forme en dehors de cette liste :
// record Losange(...) implements Forme { } // ne compile pas

// Cas tres frequent : representer un ensemble fixe d'evenements possibles.
public sealed interface Evenement permits Connexion, Deconnexion, Achat { }

record Connexion(String utilisateur) implements Evenement { }
record Deconnexion(String utilisateur) implements Evenement { }
record Achat(String utilisateur, double montant) implements Evenement { }

// On sait de maniere certaine qu'il existe exactement 3 sortes d'evenements.
// Chaque record porte en plus les donnees propres a son cas.

classDiagram
    class Forme {
        <<sealed interface>>
    }
    class Cercle {
        <<record>>
        +double rayon
    }
    class Rectangle {
        <<record>>
        +double largeur
        +double hauteur
    }
    class Triangle {
        <<record>>
        +double base
        +double hauteur
    }
    Forme <|.. Cercle : permits
    Forme <|.. Rectangle : permits
    Forme <|.. Triangle : permits

