public sealed interface Resultat permits Succes, Echec { }

record Succes(String valeur) implements Resultat { }
record Echec(String message) implements Resultat { }

// On a exactement deux issues possibles, ni plus ni moins.
// Chaque record porte la donnee utile a son cas : la valeur en cas de succes,
// le message en cas d'echec. C'est un patron tres courant pour representer
// "soit un resultat, soit une erreur" de facon sure.

sections.body:
sealed interface Forme permits Cercle, Rectangle, Triangle { }
record Cercle(double rayon) implements Forme { }
record Rectangle(double largeur, double hauteur) implements Forme { }
record Triangle(double base, double hauteur) implements Forme { }

static double aire(Forme f) {
    // Pas de branche "default" : les trois cas couvrent TOUT le type scelle.
    return switch (f) {
        case Cercle c      -> Math.PI * c.rayon() * c.rayon();
        case Rectangle r   -> r.largeur() * r.hauteur();
        case Triangle t    -> t.base() * t.hauteur() / 2;
    };
    // Si on ajoutait une 4e forme au permits, ce switch ne compilerait plus
    // tant qu'on n'aurait pas traite le nouveau cas. Securite garantie.
}
